 public String getStringExtra(String k){Object v=e.get(k);return v==null?null:String.valueOf(v);} public long getLongExtra(String k,long d){Object v=e.get(k);return v instanceof Number?((Number)v).longValue():d;} public int getIntExtra(String k,int d){Object v=e.get(k);return v instanceof Number?((Number)v).intValue():d;} public double getDoubleExtra(String k,double d){Object v=e.get(k);return v instanceof Number?((Number)v).doubleValue():d;} public boolean getBooleanExtra(String k,boolean d){Object v=e.get(k);return v instanceof Boolean?(Boolean)v:d;} public boolean hasExtra(String k){return e.containsKey(k);}
